<?php
namespace App\Models;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
final class PolicyTransaction extends Model{use HasUuids;protected$fillable=['tenant_id','policy_id','type','status','transaction_number','effective_at','requested_changes','terms_before','terms_after','premium_delta_minor','currency','reason_code','notes','requested_by','approved_by','approved_at','cancellation_rule_version_id','payment_intent_id','refund_minor','terms_hash'];protected function casts():array{return['effective_at'=>'datetime','requested_changes'=>'array','terms_before'=>'array','terms_after'=>'array','approved_at'=>'datetime'];}public function policy():BelongsTo{return$this->belongsTo(Policy::class);}public function payment():BelongsTo{return$this->belongsTo(PaymentIntentRecord::class,'payment_intent_id');}}
